                dict(label='Intereses', points=[dict(text='Las haciendas y raíces pasan a los señores de los que eran vasallos, lo que explica el apoyo de parte de la nobleza señorial a la expulsión.', quotes=[Q('ws_bando_moriscos','S.M. ha tenido por bien de hacer merced de estas haciendas, raices y muebles'), Q('es_moriscos','Valencia y de Aragón que fueron los más afectados')])]),
                dict(label='Valoración', points=[dict(text='El propio texto reconoce que los moriscos sostenían una agricultura y una industria (azúcar, arroz, regadío) que había que continuar con nuevos pobladores.', quotes=[Q('ws_bando_moriscos','puedan dar noticia á los nuevos pobladores que vinieren'.replace('puedan dar noticia á los nuevos','puedan dar noticia á los nuevos')), Q('es_moriscos','perdieron un tercio y un sexto de su población, respectivamente')])]),
