                sections=[
                  dict(label='Las estimaciones', points=[dict(text='Kamen propone 2000-2500, Llorca 10 000-15 000, Llorente más de 30 000 (31 912 ejecutados de 341 021 procesados); García Cárcel calcula unos 150 000 procesados y unas 3000 víctimas; Pérez, menos de 10 000.', quotes=[Q('es_inquisicion','desde las 2000-2500 que proponen autores como Henry Kamen'), Q('es_inquisicion','Pérez ha estimado en menos de 10 000 las sentencias a muerte seguidas de ejecución')])]),
                  dict(label='Por qué difieren', points=[dict(text='Los archivos de la Suprema solo cubren desde 1560 y la mayoría de los tribunales locales se han perdido; Lea criticó las cifras de Llorente por no basarse en estadísticas rigurosas.', quotes=[Q('es_inquisicion','Los archivos de la Suprema apenas proporcionan información acerca de las causas anteriores a 1560'), Q('es_inquisicion','han desestimado las cifras de Llorente')])]),
                  dict(label='Conclusión prudente', points=[dict(text='Es probable que nunca se conozca la cifra exacta; la leyenda negra y su revisión condicionan el debate.', quotes=[Q('es_inquisicion','es probable que nunca se sepa con seguridad el número exacto de los ejecutados por la Inquisición'), Q('en_inquisition','an estimated 3,000–5,000 were turned over to the state for execution')])]),
                ],
